import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig, Vector } from "../utils";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                // Linearly interpolate between start tile height and end tile height based on move progress
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                // If the unit has drifted significantly from its logical tile center (e.g., knockback),
                // sample height at its visual position to prevent clipping through walls.
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Apply Visual Offset (Y is down in Canvas, so subtract height to move "up")
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position (ground level) to maintain consistency with terrain sorting
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouettes
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- DRAW BASE (Ground Level) ---
        // The base should strictly align with the grid face (0,0 local)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);
            ctx.save();
            // Center of base sprite ellipse is at (64, 79). 
            // We draw at (-64, -79) to align it with (0,0).
            ctx.drawImage(assets.base, -64, -79); 

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        // Visual Base Top Surface is approx -16px relative to base drawing origin.
        // We want feet (~ +15px in local body space) to land at -16px.
        // So we shift up by ~ -31px.
        const BODY_GROUNDING_OFFSET = -31; 

        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        // Applies scale stretch and alpha fade if spawning
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);
        const yOffset = -85 * scale; // Moved up higher because body is now higher

        ctx.save();
        ctx.translate(x, y + yOffset);
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);
        ctx.globalAlpha = alpha;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -75; // Adjusted head position for icons

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT
        if (agent.dotTimer > 0) {
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; 
            const icon = AssetManager.getStatusIcon('POISON'); 
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';
            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; 
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
                if (cycle < 1) {
                    ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
                }
            }
        }

        // 5. HoT
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 
        const lineCount = 5 + Math.floor(progress * 8); 
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; 
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
        }

        // 2. Converging Rings
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

            ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
            ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
        }

        // 3. Hand Glow
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

        // 4. Final Flash
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    private drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
         if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.visual) {
                const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
                ctx.save();
                // Move Higher relative to Body top (approx -120 local)
                ctx.translate(0, -110);
                const pulse = 1 + Math.sin(t * 10) * 0.1;
                ctx.scale(pulse, pulse);

                const glow = AssetManager.getGlowSprite(skill.color);
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = 0.6;
                ctx.drawImage(glow, -32, -32, 64, 64);
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1.0;

                ctx.drawImage(icon, -12, -12, 24, 24);

                // Cast Bar
                ctx.fillStyle = '#000';
                ctx.fillRect(-14, 20, 28, 5); 
                ctx.fillStyle = skill.color;
                const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
                ctx.fillRect(-14, 20, 28 * pct, 5);
                ctx.restore();
            }
        }
    }

    // =================================================================================
    // STYLE A: THE IMPERIAL LEGION
    // =================================================================================
    private drawImperialLegion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#3b82f6'; 
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;

        if (!isSilhouette) {
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff'); 
            grad.addColorStop(0.5, '#93c5fd'); 
            grad.addColorStop(1, '#2563eb');   
            accent = '#3b82f6'; 
        }

        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        this.drawImperialWeapon(ctx, agent.role, grad, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-18, -30); ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15); ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, -25); ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25); ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            ctx.moveTo(-12, -25); ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();
            // Rivets
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            ctx.rect(-10, -14, 20, 16);
        } else {
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fef08a'; ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155'; ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, grad: any, accent: string, isSilhouette: boolean) {
        if (isSilhouette) {
            ctx.strokeStyle = '#3b82f6';
            ctx.lineWidth = 2;
        }

        if (role === Role.WARRIOR) {
            ctx.beginPath();
            ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
            ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);
            if (isSilhouette) ctx.stroke();
            else {
                ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
            }
        } else if (role === Role.RANGER) {
            ctx.rotate(-Math.PI/2);
            if (isSilhouette) ctx.strokeRect(0, -3, 30, 4);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 30, 4);
                ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
            }
        } else if (role === Role.MAGE || role === Role.SUPPORT) {
            if (isSilhouette) ctx.strokeRect(-2, -40, 4, 50);
            else {
                ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
                const glow = AssetManager.getGlowSprite(accent);
                ctx.save(); ctx.globalCompositeOperation = 'lighter';
                ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
                ctx.fillStyle = accent; ctx.fillRect(-6, -45, 12, 12);
            }
        }
    }

    // =================================================================================
    // STYLE B: THE ARCANE COVENANT
    // =================================================================================
    private drawArcaneCovenant(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = this.getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
             ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
             ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
             ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
             ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) ctx.stroke();
        else ctx.fill();

        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;
                ctx.save(); ctx.translate(ox, oy - 20);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
                }
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);
            if(!isSilhouette) {
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke(); else { ctx.fillStyle = glowColor; ctx.fill(); }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
                ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }

    private getCastProgress(agent: Agent): number {
        if (agent.castingSkillIdx === -1) return 0;
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return 0;
        const raw = agent.castTimer / skill.cast;
        return Math.max(0, Math.min(1, 1 - raw)); 
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES, MAX_TERRAIN_TIER } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, ISO_SCALE_Y } from "../utils";
import { AssetManager } from "../assets";
import { Hex, Skill, Projectile } from "../../types";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// OPTIMIZATION: Precompute Hex Polygon Offsets to avoid Trig in render loop
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    private _dangerZones = new Map<string, {color: string, progress: number}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // Using raw HexUtils range which creates arrays, acceptable for small radii
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            this._dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                // HEIGHT AWARE RANGE CHECK
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => this.drawIsoBlock(
                    ctx, 
                    px, visualY, 
                    HEX_SIZE, h, 
                    theme, 
                    flash, 
                    isRange, rangeColor, 
                    isHover, 
                    dangerInfo, 
                    hasUnit,
                    lightColor,
                    Math.min(1, lightIntensity),
                    q, r, scene.textureType,
                    specialStatus,
                    globalTime
                )
            });
        }

        return list;
    }

    private drawIsoBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any, 
        flash: any, 
        isRange: boolean, rangeColor: string, 
        isHover: boolean, 
        dangerInfo: {color: string, progress: number} | undefined, 
        hasUnit: boolean,
        lightColor: string | null,
        lightIntensity: number,
        q: number = 0, r: number = 0, textureType: string = 'VOID',
        specialStatus: string | undefined,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; // Visual foundation thickness

        // This is the TOP face Y level relative to ground (y)
        const topY = height; 

        // Use precomputed corners to avoid trig calls per tile
        const traceTopFace = () => {
            ctx.beginPath();
            const c0 = HEX_CORNERS[0];
            ctx.moveTo(x + c0.x, y + c0.y - topY);
            for (let i = 1; i < 6; i++) {
                const c = HEX_CORNERS[i];
                ctx.lineTo(x + c.x, y + c.y - topY);
            }
            ctx.closePath();
        };

        // --- 1. Draw Side Faces (The Stack) ---
        // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            // Top vertices (Visual Top)
            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            // Bottom vertices (Visual Base/Foundation)
            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            // Alternate brightness for 3D effect
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); // Darker at the very bottom foundation

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom); // Bottom Left (Foundation)
            ctx.lineTo(x2, y2_bottom); // Bottom Right (Foundation)
            ctx.lineTo(x2, y2_top);    // Top Right
            ctx.lineTo(x1, y1_top);    // Top Left
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect (Tactics Ogre)
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // --- 2. Draw Top Face (Base) ---
        traceTopFace();

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- 2.5 Draw Terrain Texture (Detailing) ---
        this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

        // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
        if (specialStatus) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // --- 2.7 AOE TELEGRAPH ---
        if (dangerInfo) {
            traceTopFace(); 
            ctx.save();
            // 1. Tile Coloring
            const opacity = 0.1 + dangerInfo.progress * 0.6;
            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); 

            // 2. Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }

    private noise(q: number, r: number) {
        return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
    }

    private drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        size: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = this.noise(q, r);
        const n2 = this.noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (this.noise(q+i, r) - 0.5) * 20;
                const oy = (this.noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState } from "../../types";
import { BLOCK_HEIGHT } from "../../constants";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    // Optimization: Reuse Stacking Map to reduce GC
    private _stackingMap = new Map<number, Agent[]>();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Gravity (Z-axis)
        if (isDead || isAirborne) {
            a.physics.vz -= GRAVITY * dt;
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Vertical interpolation logic can be handled in UnitRenderSystem, 
        // here we mostly care about X/Y transition for logic updates

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range (With Height Bonus)
        const effRange = this.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        if (HexUtils.dist(a, targetHex) <= effRange) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            if (engine.isBlocked(next.q, next.r, a.id)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE); 
                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this._stackingMap.clear();
        const map = this._stackingMap;

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range (using Height Bonus)
        const effRange = this.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);
            const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);

            // SUCCESS CONDITION: Inside Range? (Check height for this specific tile)
            const currentEffRange = this.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine);
            if (HexUtils.dist(currentHex, targetHex) <= currentEffRange) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check (Always active)
                if (engine.map.hasObstacleHash(nextH)) continue;

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                const nextHexCoord = HexUtils.unhash(nextH);
                const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                // Allow climb/drop if deltaH <= Jump Height (in pixels)
                // Using max(1, jump) to ensure at least 1 block can be traversed by default
                const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                if (deltaH > maxClimb) {
                    continue; // Too steep!
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            // Exact check happens inside the loop using effective range.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { AssetManager } from "./assets";
import { Hex, GameEvent, Skill, SceneTheme, Team } from "../types";
import { HEX_SIZE } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// Constants
const HUD_TEXT_OFFSET = 40; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 86; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // Camera Shake Effects
    private shakeTimer = 0; 
    private shakeIntensity = 0;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        if (this.shakeTimer > 0) {
            this.shakeTimer -= dt;
        }

        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;

        // Propagate updates to sub-systems
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                 const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
                 const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; // Crit Red vs White
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

                 // --- BEAM VISUAL CHECK ---
                 if (event.skill && event.skill.visual === 'BEAM' && event.sourceId) {
                     const source = engine.agents.find(a => a.id === event.sourceId);
                     if (source) {
                         // Use visual position for beam start/end
                         const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                         const sH = this.grid.getTerrainHeight(sHex.q, sHex.r, engine);
                         const sx = source.px;
                         const sy = source.py - sH - 40; 
                         const tH = terrainHeight; 
                         const tx = event.pos.x;
                         const ty = event.pos.y - tH - 20; 
                         this.vfx.spawnBeam(sx, sy, tx, ty, event.skill.color);
                     }
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                     const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = event.pos.y - terrainHeight - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         this.vfx.spawnDomainExpansion(event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.triggerCameraShake(0.5, 8); 
                     }
                 }
            }

            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            switch (event.type) {
                case 'DAMAGE': 
                    this.vfx.spawnExplosion(event.pos.x, visualY, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK'); 
                    break;
                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;
                case 'DEATH':
                    // Trigger massive shatter effect
                    // event.team is passed from AgentManager
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    this.vfx.spawnUnitShatter(event.pos.x, visualY, team);
                    break;
                case 'SPAWN':
                    // Trigger spawn visual (Beam in)
                    this.vfx.spawnTeleport(event.pos.x, visualY, event.color || '#fff');
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.triggerCameraShake(0.6, 15); 
            this.vfx.spawnDivinePillar(event.pos.x, visualY, color, 1.5);
            this.vfx.spawnShockwave(event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            this.vfx.spawnDivinePillar(tilePos.x, tileVisualY, color, 0.7, delay);
                            this.vfx.addGridFlash(h.q, h.r, color);
                        } else {
                            this.vfx.addGridFlash(h.q, h.r, color);
                        }
                    }
                });
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 3.0);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        this.vfx.addGridFlash(h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            this.vfx.addDecal(event.pos.x, visualY, color);
                        }
                    }
                });
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                this.vfx.addImpact(event.pos.x, visualY, color, 'RING', 0.8);
                this.vfx.spawnExplosion(event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    private triggerCameraShake(duration: number, intensity: number) {
        this.shakeTimer = duration;
        this.shakeIntensity = intensity;
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Complex Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.drawComplexBackground(ctx, canvasWidth, canvasHeight, scene);

        // 2. Camera Transform application
        ctx.save();

        let shakeOffsetX = 0;
        let shakeOffsetY = 0;
        if (this.shakeTimer > 0) {
            shakeOffsetX = (Math.random() - 0.5) * this.shakeIntensity;
            shakeOffsetY = (Math.random() - 0.5) * this.shakeIntensity;
        }

        ctx.translate(canvasWidth / 2 + shakeOffsetX, canvasHeight / 2 + shakeOffsetY);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfx.collectRenderables(
            engine,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Refactored: Iterate over Map<string, string>
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         // Use the specific type stored in the Map, or fallback to default
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y + 20);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Atmospheric Fog
        this.drawAtmosphericFog(ctx, engine.mapConfig.w * HEX_SIZE * 2, engine.mapConfig.h * HEX_SIZE * 2, scene);

        // 6. Tactical Overlay Lines (World Space)
        this.drawTacticalOverlay(ctx, engine, highlight);

        // 7. Top VFX
        this.vfx.drawTopLayerParticles(ctx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 8. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 9. Holographic Director HUD (Screen Space, but Diegetic)
        if (engine.directorTargetId) {
            const focus = engine.agents.find(a => a.id === engine.directorTargetId);
            if (focus) {
                // We draw this *inside* the camera transform if we want it tied to world, 
                // BUT the requirement is screen corner.
                // To make it look "in-world" but stuck to corner, we draw it after restore() but apply manual perspective.
                ctx.restore(); // Exit Camera
                this.drawHolographicHUD(ctx, focus, canvasWidth, canvasHeight, camera);
                ctx.save(); // Restore dummy save to match final restore() call
            } else {
                ctx.restore();
                ctx.save();
            }
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Final restore

        // 10. Debug Overlay
        this.drawDebugOverlay(ctx, fps);
    }

    // =========================================================================================
    // 📺 HOLOGRAPHIC TACTICAL HUD (Diegetic UI)
    // =========================================================================================

    private drawHolographicHUD(ctx: CanvasRenderingContext2D, agent: Agent, w: number, h: number, cam: Camera) {
        // Position: Top Right, floating
        const hudX = w - 260; 
        const hudY = 60;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        let alphaMod = 1.0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 10;
            gy = (Math.random() - 0.5) * 5;
            alphaMod = 0.5 + Math.random() * 0.5;
            if (Math.random() > 0.8) alphaMod = 0.2; // Flicker out
        }

        // --- 2. Perspective Transform ---
        // CHANGED: Use Horizontal Shear (c=-0.15) instead of Vertical Shear (b=-0.12).
        // This keeps text horizontal (better readability) while making the panel lean left.
        // matrix(1, 0, -0.15, 1, x, y)
        ctx.transform(1, 0, -0.15, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.globalAlpha = alphaMod;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (this.globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = (0.5 + Math.sin(this.globalTime * 20) * 0.5) * alphaMod;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0 * alphaMod;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        // Tether should NOT be transformed by the panel skew to look connected to world
        // But since we are in transformed state, we draw a short "antenna" instead.
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }

    // =========================================================================================
    // ⚔️ TACTICAL OVERLAY SYSTEM (Visualizing AI Intent)
    // =========================================================================================

    private drawTacticalOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null) {
        ctx.save();

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = this.grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = this.grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = this.grid.getTerrainHeight(dest.q, dest.r, engine);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = this.grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(this.globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    // =========================================================================================
    // 🌌 COMPLEX BACKGROUND SYSTEM
    // =========================================================================================

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme): void {
        const t = this.globalTime;

        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.6, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#000');           // Below Horizon (Ground blend)
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 2. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 3. Distant Silhouette / Terrain (Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = scene.background; // Blend with sky color but darker
            ctx.globalAlpha = 0.5;

            const drawMountainLayer = (speed: number, yOffset: number, roughness: number) => {
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    // Simple procedural terrain noise
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.6 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer
            drawMountainLayer(0.01, 0, 50);
            // Near Layer (Darker)
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.02, 50, 30);
        }

        // 4. Special Sky Features
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            // Draw multiple sine waves to simulate a flowing river
            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // Add particles in the river
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            // --- VERTICAL CURTAINS ---
            const colors = ['#34d399', '#22d3ee', '#818cf8']; // Green, Cyan, Indigo

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); // Top Right
                ctx.lineTo(0, 0); // Top Left
                ctx.fill();
            }

        } else if (scene.bgFeature === 'CANOPY') {
            // --- GOD RAYS ---
            ctx.globalCompositeOperation = 'overlay';
            const centerX = w * 0.8;
            const centerY = -100;

            const grad = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, w);
            grad.addColorStop(0, '#fef08a'); // Yellow light
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.2;

            // Draw Angular Rays
            for(let i=0; i<6; i++) {
                const angle = Math.PI / 2 + Math.sin(t * 0.2 + i) * 0.2 + (i * 0.3);
                const width = Math.PI / 16;

                ctx.beginPath();
                ctx.moveTo(centerX, centerY);
                ctx.lineTo(centerX + Math.cos(angle - width) * w * 1.5, centerY + Math.sin(angle - width) * w * 1.5);
                ctx.lineTo(centerX + Math.cos(angle + width) * w * 1.5, centerY + Math.sin(angle + width) * w * 1.5);
                ctx.fill();
            }
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            // Rising heat distortion visual
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme) {
        const t = this.globalTime;

        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); // Use pre-rendered sprite
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Moving clouds across the map
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; // Pulse opacity
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }

    private drawDebugOverlay(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES, MAX_TERRAIN_TIER } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, ISO_SCALE_Y } from "../utils";
import { AssetManager } from "../assets";
import { Hex, Skill, Projectile } from "../../types";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// OPTIMIZATION: Precompute Hex Polygon Offsets to avoid Trig in render loop
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    private _dangerZones = new Map<string, {color: string, progress: number}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // Using raw HexUtils range which creates arrays, acceptable for small radii
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            this._dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                // HEIGHT AWARE RANGE CHECK
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => this.drawIsoBlock(
                    ctx, 
                    px, visualY, 
                    HEX_SIZE, h, 
                    theme, 
                    flash, 
                    isRange, rangeColor, 
                    isHover, 
                    dangerInfo, 
                    hasUnit,
                    lightColor,
                    Math.min(1, lightIntensity),
                    q, r, scene.textureType,
                    specialStatus,
                    globalTime
                )
            });
        }

        return list;
    }

    private drawIsoBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any, 
        flash: any, 
        isRange: boolean, rangeColor: string, 
        isHover: boolean, 
        dangerInfo: {color: string, progress: number} | undefined, 
        hasUnit: boolean,
        lightColor: string | null,
        lightIntensity: number,
        q: number = 0, r: number = 0, textureType: string = 'VOID',
        specialStatus: string | undefined,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; // Visual foundation thickness

        // This is the TOP face Y level relative to ground (y)
        const topY = height; 

        // Use precomputed corners to avoid trig calls per tile
        const traceTopFace = () => {
            ctx.beginPath();
            const c0 = HEX_CORNERS[0];
            ctx.moveTo(x + c0.x, y + c0.y - topY);
            for (let i = 1; i < 6; i++) {
                const c = HEX_CORNERS[i];
                ctx.lineTo(x + c.x, y + c.y - topY);
            }
            ctx.closePath();
        };

        // --- 1. Draw Side Faces (The Stack) ---
        // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            // Top vertices (Visual Top)
            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            // Bottom vertices (Visual Base/Foundation)
            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            // Alternate brightness for 3D effect
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); // Darker at the very bottom foundation

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom); // Bottom Left (Foundation)
            ctx.lineTo(x2, y2_bottom); // Bottom Right (Foundation)
            ctx.lineTo(x2, y2_top);    // Top Right
            ctx.lineTo(x1, y1_top);    // Top Left
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect (Tactics Ogre)
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // --- 2. Draw Top Face (Base) ---
        traceTopFace();

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- 2.5 Draw Terrain Texture (Detailing) ---
        this.drawTerrainDetail(ctx, x, y - topY, size, q, r, textureType, theme.detail);

        // --- 2.6 SPECIAL STATUS FLOOR EFFECT ---
        if (specialStatus) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // --- 2.7 AOE TELEGRAPH ---
        if (dangerInfo) {
            traceTopFace(); 
            ctx.save();
            // 1. Tile Coloring
            const opacity = 0.1 + dangerInfo.progress * 0.6;
            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); 

            // 2. Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 3. Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = (y - topY) - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // --- 3. Dynamic Lighting ---
        if (lightColor && lightIntensity > 0) {
            traceTopFace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // --- 4. Interactive Overlays ---
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            traceTopFace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }

    private noise(q: number, r: number) {
        return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
    }

    private drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        size: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = this.noise(q, r);
        const n2 = this.noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (this.noise(q+i, r) - 0.5) * 20;
                const oy = (this.noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState } from "../../types";
import { BLOCK_HEIGHT } from "../../constants";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    // Optimization: Reuse Stacking Map to reduce GC
    private _stackingMap = new Map<number, Agent[]>();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Gravity (Z-axis)
        if (isDead || isAirborne) {
            a.physics.vz -= GRAVITY * dt;
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Vertical interpolation logic can be handled in UnitRenderSystem, 
        // here we mostly care about X/Y transition for logic updates

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range (With Height Bonus)
        const effRange = this.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        if (HexUtils.dist(a, targetHex) <= effRange) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            if (engine.isBlocked(next.q, next.r, a.id)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE); 
                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this._stackingMap.clear();
        const map = this._stackingMap;

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range (using Height Bonus)
        const effRange = this.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);
            const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);

            // SUCCESS CONDITION: Inside Range? (Check height for this specific tile)
            const currentEffRange = this.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine);
            if (HexUtils.dist(currentHex, targetHex) <= currentEffRange) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check (Always active)
                if (engine.map.hasObstacleHash(nextH)) continue;

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                const nextHexCoord = HexUtils.unhash(nextH);
                const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                // Allow climb/drop if deltaH <= Jump Height (in pixels)
                // Using max(1, jump) to ensure at least 1 block can be traversed by default
                const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                if (deltaH > maxClimb) {
                    continue; // Too steep!
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            // Exact check happens inside the loop using effective range.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, GameEventType, AnimState, Hex } from "../../types";
import { HexUtils, Vector } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

const UNIT_CHEST_HEIGHT = 40;
const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class CombatSystem {
    public projectiles: Projectile[] = [];

    // =========================================================================================
    // ⚔️ MAIN UPDATE LOOP
    // =========================================================================================

    public update(dt: number, engine: GameEngine) {
        this.updateProjectiles(dt, engine);

        // Handle Casting Logic for Agents
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.updateAgentCasting(a, dt, engine);
            }
        });
    }

    private updateAgentCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0) {
            const skillName = a.skills[a.castingSkillIdx]?.name || '技能';
            engine.log(a, '中斷', null, `${skillName} 被打斷`);

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution
            if (s.projectileSpeed && s.projectileSpeed > 0) {
                 this.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    // =========================================================================================
    // 🏹 PROJECTILE LOGIC
    // =========================================================================================

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let tx = 0, ty = 0;
        let tid = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 tx = p.x; ty = p.y;
                 tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 tx = source.target.px; ty = source.target.py;
                 tid = source.target.id;
             } else {
                 return; // No target
             }
             targetPos = {x: tx, y: ty};
             this.createProjectile(source, skill, targetPos, tid, engine);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });

        } else {
            // Single Target Projectile
            const targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
            targets.forEach(t => {
                 targetPos = {x: t.px, y: t.py};
                 this.createProjectile(source, skill, targetPos, t.id, engine);
                 engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: t.id });
            });
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string, engine: GameEngine) {
        // Height Correction: Projectiles spawn from chest height, not feet
        const h = engine.map.getTerrainHeight(source.q, source.r);

        this.projectiles.push({
            id: Math.random().toString(),
            x: source.px, 
            y: source.py, // Logic position
            startX: source.px, 
            startY: source.py,
            targetId: targetId,
            targetPos: targetPos,
            speed: skill.projectileSpeed!,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            trail: []
        });
    }

    private updateProjectiles(dt: number, engine: GameEngine) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            // Homing logic: update target position if unit moves
            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = p.speed * dt;

            p.trail.push({x: p.x, y: p.y});
            if (p.trail.length > 20) p.trail.shift();

            // Hit Detection
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId) || engine.agents[0]; // Fallback

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const radius = p.skill.aoeRadius || 1;
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);
                    targets.forEach(t => { if (source) this.applyDamage(source, t, p.skill, hitPos, engine); });
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) this.applyDamage(source, target, p.skill, undefined, engine);
                    }
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: p.x, y: p.y}, skill: p.skill });
                }

                // Remove projectile (swap and pop for performance)
                const lastIdx = this.projectiles.length - 1;
                if (i !== lastIdx) {
                    this.projectiles[i] = this.projectiles[lastIdx];
                }
                this.projectiles.pop();

            } else {
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    // =========================================================================================
    // 💥 SKILL EXECUTION
    // =========================================================================================

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: Hex | null = null;

        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            // Single Target - Verify Height-Aware Range
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                const actualDist = HexUtils.dist(source, source.target);

                if (actualDist <= effectiveRange) {
                    targets = [source.target];
                }
            }
        }

        const origin = {x: source.px, y: source.py};

        targets.forEach(t => this.applyDamage(source, t, skill, origin, engine));
        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public applyDamage(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            const originX = origin ? origin.x : source.px;
            const originY = origin ? origin.y : source.py;
            let dx = target.px - originX;
            let dy = target.py - originY;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len > 0) {
                dx /= len; dy /= len;
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += dx * impactForce;
                target.physics.vy += dy * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        engine.log(source, '命中', target.id, `${skill.name} ${rawDmg > 0 ? `-${rawDmg}` : (rawDmg < 0 ? `+${-rawDmg}` : '')}`);
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            // --- WEIGHTED KNOCKBACK LOGIC ---

            // 1. Calculate push tiles: (Skill Force - Unit Weight)
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            // Iterative push
            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                // Find best neighbor matching direction
                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    // Check Validity
                    if (!engine.isValid(bestN.q, bestN.r)) break; // Map Edge
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; // Wall collision

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);

                    // Height Check (Tactics Ogre Physics)
                    // If hitting a wall > 1 block high -> STOP
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) {
                        break; 
                    }

                    // If falling off a cliff > 2 blocks -> STOP (or future: fall damage)
                    // Currently stopping to prevent weirdness, but allow small drops
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) {
                        break; 
                    }

                    // Move one step
                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);

                // Add upward impulse for "hop" effect visually
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

