                      className={`px-2 md:px-3 py-1 bg-emerald-600 hover:bg-emerald-500 text-white text-[10px] md:text-xs font-bold rounded flex items-center gap-1 ${winner !== null ? 'opacity-30 cursor-not-allowed' : ''}`}
                    >
