                </div>

                <div className="flex items-center gap-4 shrink-0">
                    <div className="flex items-center bg-slate-800 rounded px-2 py-1 border border-slate-700">
                        <span className="text-[9px] text-slate-500 mr-1">血量</span>
                        <input 
                            disabled={isPlaying || winner !== null}
                            type="number" 
                            className={`w-10 bg-transparent text-[10px] text-center focus:outline-none ${isPlaying || winner !== null ? 'opacity-50' : ''}`}
                            value={hpInput}
                            onChange={(e) => setHpInput(parseInt(e.target.value) || 1)}
                        />
                    </div>

                    <button 
                        className="md:hidden p-2 bg-slate-800 border border-slate-700 rounded text-slate-400 active:bg-slate-700"
                        onClick={() => setShowMobileInspector(!showMobileInspector)}
                    >
                        ⚙️
                    </button>
                </div>
            </div>
        </div>

        {/* Resizer Handle: Hidden in Showcase */}
        {!isShowcaseMode && (
            <div 
                className="hidden md:flex w-2 bg-slate-950 hover:bg-blue-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-30"
                onMouseDown={startResizing}
            >
                <div className="w-1 h-8 bg-slate-700 rounded"></div>
            </div>
        )}

        {/* Inspector: Hidden in Showcase */}
        <div 
            className={`hidden md:flex flex-col shrink-0 z-10 shadow-xl bg-slate-900 border-l border-slate-700 transition-all duration-300 ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}`}
            style={{ width: isShowcaseMode ? 0 : sidebarWidth }}
        >
            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
        </div>

        {showMobileInspector && !isShowcaseMode && (
            <div className="fixed inset-0 z-50 flex flex-col md:hidden animate-fade-in">
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowMobileInspector(false)}></div>
                <div className="absolute inset-x-2 bottom-2 top-12 bg-slate-900 rounded-lg shadow-2xl border border-slate-700 flex flex-col overflow-hidden animate-slide-up">
                    <div className="flex justify-between items-center p-3 border-b border-slate-700 bg-slate-950 shrink-0">
                        <span className="font-bold text-slate-300 text-sm">監控面板</span>
                        <button 
                            onClick={() => setShowMobileInspector(false)}
                            className="text-slate-400 hover:text-white px-2 py-1 bg-slate-800 rounded text-xs"
                        >
                            關閉 ✕
                        </button>
                    </div>
                    <div className="flex-1 overflow-hidden relative">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current}
                            logs={[]}
                            db={engineRef.current.skillDB}
                            onHoverSkill={setHoveredSkill}
                        />
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { Team, ToolType, Hex, Skill, GameEvent } from '../types';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; // New: Specific type
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); // Adjusted default zoom
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // Interaction State
    const draggedAgentRef = useRef<Agent | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isDraggingUnit = useRef(false);

    const isPanning = useRef(false);
    const isPainting = useRef(false); // New: Track if painting
    const lastPaintHex = useRef<string>(""); // Prevent spamming same tile

    const pointerDownStart = useRef<{x: number, y: number} | null>(null);
    const pendingAction = useRef<boolean>(false); 

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        // Grid Top-Left is roughly (0,0) in Axial
        // Center is (w/2, h/2)
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        // 1. Terrain Height offset: Blocks go "up" (negative Y), so the visual center of the top face is higher than p.y
        // We estimate average height to be around 2 blocks
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        // Trigger centering when:
        // 1. Transition IN starts (New map generated in Showcase)
        // 2. Showcase Mode is entered toggled on
        // 3. Map dimensions change (manual settings)
        if (isShowcaseMode || transitionPhase === 'IN') {
            // Wait for CSS transition (300ms) to finish before centering
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             // Also recenter when exiting showcase mode
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                // Immediately update canvas resolution to match container
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                // If map is empty (initial load), center it
                if (engine.agents.length === 0) {
                    centerCamera();
                }

                // CRITICAL FIX: Synchronous Redraw
                // Immediately draw the frame to prevent the canvas from appearing blank/black 
                // between the resize (clear) and the next animation frame.
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);

        // Force initial center
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        // Define draw function that can be called externally via ref
        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                const highlight = draggedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 
            }
        };

        // Assign to ref for ResizeObserver
        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // Measure FPS
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Step
            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];

                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;

                    // Collect events from this tick to avoid dropping them
                    // or processing them multiple times in the render loop
                    frameEvents.push(...engine.events);
                }

                // Only process events if we actually ticked logic this frame
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Visual Update
            rendererRef.current.update(dt / 1000, engine);

            // Handle Transition Animation Progress
            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                // Transition usually lasts 1.5s total logic in App, let's map 0-1 over 1.2s for visual
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getHexFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            // Use renderer's accurate 3D picking logic
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            if (hex) return hex;

            // Picking fallback in 3D is tricky, we rely on the grid system's robustness
            return HexUtils.fromPx(
                mouseX / camera.current.zoom + camera.current.x,
                mouseY / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        // HIT TEST for Unit Selection (Prioritizes Units over Tiles)
        const getHitAgent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;
            const wx = mouseX / camera.current.zoom + camera.current.x;
            const wy = mouseY / camera.current.zoom + camera.current.y;

            // Sort agents by Y (depth) desc so we pick the one in front (visually on top)
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;

                // Get terrain height for this agent's position
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);

                // Visual base position
                const baseX = agent.px;
                const baseY = agent.py - h;

                // Hitbox: Centered horizontally on agent.px
                // Vertical: From BaseY up to Head. Approx 80px tall.
                // Center of hitbox roughly at (baseX, baseY - 40)
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 

                // 30px width radius, 50px height radius (Total 60x100 box)
                if (dx < 30 && Math.abs(dy) < 50) {
                    return agent;
                }
            }
            return null;
        };

        const getWorldPosFromEvent = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;
            const wx = mouseX / camera.current.zoom + camera.current.x;

            // Get height at this position (approximate)
            const hex = rendererRef.current.getHexAtScreenPoint(mouseX, mouseY, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);

            const wy = mouseY / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const handleActionAt = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; // Prevent spam on same tile

            lastPaintHex.current = k;

            if (tool === ToolType.ADD_BLUE) engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) engine.addAgent(Team.RED, h.q, h.r, hpInput);
            else if (tool === ToolType.OBSTACLE) {
                // Ensure we remove agent if painting over
                if (engine.getAgentAt(h.q, h.r)) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
            }
            else if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (engine.getAgentAt(h.q, h.r)) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
            }
        };

        const handleMouseDown = (e: MouseEvent) => {
            pointerDownStart.current = { x: e.clientX, y: e.clientY };

            if (e.button === 2) {
                isPanning.current = true;
                pendingAction.current = false;
                return;
            }

            // 1. Try to hit an agent first (Screen Space Hitbox)
            const hitAgent = getHitAgent(e);

            if (hitAgent && tool === ToolType.SELECT) {
                // Clicking a unit in Select Mode -> Select/Drag
                pendingAction.current = false;
                onSelect(hitAgent);
                if (!engine.isRunning) {
                    draggedAgentRef.current = hitAgent;
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                    isDraggingUnit.current = true;
                }
                return;
            }

            // 2. Fallback to Tile Logic
            const h = getHexFromEvent(e);

            // Legacy check: engine.getAgentAt uses spatial hash, which might miss if visual is offset
            // But we already did getHitAgent, so this is mostly for overlapping tiles
            const gridAgent = engine.getAgentAt(h.q, h.r);
            if (gridAgent && tool === ToolType.SELECT && !hitAgent) {
                 pendingAction.current = false;
                 onSelect(gridAgent);
                 if (!engine.isRunning) {
                    draggedAgentRef.current = gridAgent;
                    dragStartHex.current = { q: gridAgent.q, r: gridAgent.r };
                    isDraggingUnit.current = true;
                 }
                 return;
            }

            // Clicking empty space or Painting tools -> Start Painting/Action
            pendingAction.current = true;
            isPanning.current = false;

            // If tool is a "painting" tool, start immediate paint
            if (!engine.isRunning && tool !== ToolType.SELECT) {
                isPainting.current = true;
                lastPaintHex.current = ""; // Reset
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }
        };

        const handleMouseMove = (e: MouseEvent) => {
            const h = getHexFromEvent(e);
            if (engine.isValid(h.q, h.r)) {
                hoveredHexRef.current = h;
            } else {
                hoveredHexRef.current = null;
            }

            // Cursor Feedback for Hovering Units
            if (tool === ToolType.SELECT && !isDraggingUnit.current && !isPanning.current) {
                const hit = getHitAgent(e);
                if (canvasRef.current) {
                    canvasRef.current.style.cursor = hit ? 'pointer' : 'default';
                }
            } else if (isDraggingUnit.current && canvasRef.current) {
                canvasRef.current.style.cursor = 'grabbing';
            }

            if (isPanning.current) {
                camera.current.x -= e.movementX / camera.current.zoom;
                camera.current.y -= e.movementY / camera.current.zoom;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const wPos = getWorldPosFromEvent(e);
                draggedAgentRef.current.px = wPos.x;
                draggedAgentRef.current.py = wPos.y;
                return;
            }

            // Paint Mode Logic
            if (isPainting.current && !engine.isRunning) {
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }

            if (pendingAction.current && pointerDownStart.current && !isPainting.current) {
                const dx = e.clientX - pointerDownStart.current.x;
                const dy = e.clientY - pointerDownStart.current.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    pendingAction.current = false;
                    isPanning.current = true;
                    camera.current.x -= e.movementX / camera.current.zoom;
                    camera.current.y -= e.movementY / camera.current.zoom;
                }
            }
        };

        const handleMouseUp = (e: MouseEvent) => {
            isPainting.current = false;
            lastPaintHex.current = "";

            if (isPanning.current) {
                isPanning.current = false;
                pointerDownStart.current = null;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const h = getHexFromEvent(e);
                const agent = draggedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    // Update Engine Logic Position
                    engine.updateAgentPosition(agent, h.q, h.r);

                    // Update Visuals to match Logic (Snap to tile center)
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x;
                    agent.py = p.y;
                } else {
                    // Revert to start
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x;
                        agent.py = p.y;

                        // Ensure engine map is consistent (just in case)
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }

                draggedAgentRef.current = null;
                dragStartHex.current = null;
                isDraggingUnit.current = false;
                onSelect(agent);
                if (canvasRef.current) canvasRef.current.style.cursor = 'default';
                return;
            }

            if (pendingAction.current) {
                pendingAction.current = false;
                const h = getHexFromEvent(e);

                if (tool === ToolType.SELECT) {
                    // Try hit agent again just in case click didn't move
                    const hitAgent = getHitAgent(e);
                    if (hitAgent) onSelect(hitAgent);
                    else onSelect(null);
                } 
            }

            pointerDownStart.current = null;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, GameEventType, AnimState, Hex } from "../../types";
import { HexUtils, Vector } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

const UNIT_CHEST_HEIGHT = 40;
const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class CombatSystem {
    public projectiles: Projectile[] = [];

    // =========================================================================================
    // ⚔️ MAIN UPDATE LOOP
    // =========================================================================================

    public update(dt: number, engine: GameEngine) {
        this.updateProjectiles(dt, engine);

        // Handle Casting Logic for Agents
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.updateAgentCasting(a, dt, engine);
            }
        });
    }

    private updateAgentCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0) {
            const skillName = a.skills[a.castingSkillIdx]?.name || '技能';
            engine.log(a, '中斷', null, `${skillName} 被打斷`);

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution Branch: Projectile vs Instant
            // Rule: Force projectile logic if visual implies it, even if data is missing speed
            const visualImpliesProjectile = ['ARROW', 'FIREBALL', 'BOLT', 'BOMB'].includes(s.visual || '');
            const hasSpeed = s.projectileSpeed && s.projectileSpeed > 0;

            if (hasSpeed || visualImpliesProjectile) {
                 // Safety: Ensure valid speed
                 if (!s.projectileSpeed || s.projectileSpeed <= 0) {
                     s.projectileSpeed = 450; 
                 }
                 this.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    // =========================================================================================
    // 🏹 PROJECTILE LOGIC
    // =========================================================================================

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        // Fallback Visual: Ensure no invisible projectiles
        if (!skill.visual) {
            skill.visual = 'BOLT'; 
        }

        let tx = 0, ty = 0;
        let tid = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 tx = p.x; ty = p.y;
                 tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 tx = source.target.px; ty = source.target.py;
                 tid = source.target.id;
             } else {
                 return; // No target
             }
             targetPos = {x: tx, y: ty};
             this.createProjectile(source, skill, targetPos, tid, engine);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });

        } else {
            // Single Target Projectile
            const targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
            targets.forEach(t => {
                 targetPos = {x: t.px, y: t.py};
                 this.createProjectile(source, skill, targetPos, t.id, engine);
                 engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: t.id });
            });
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string, engine: GameEngine) {
        this.projectiles.push({
            id: Math.random().toString(),
            x: source.px, 
            y: source.py, 
            startX: source.px, 
            startY: source.py,
            targetId: targetId,
            targetPos: targetPos,
            speed: skill.projectileSpeed || 450, // Safe default
            skill: skill,
            sourceId: source.id,
            team: source.team,
            trail: []
        });
    }

    private updateProjectiles(dt: number, engine: GameEngine) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            // Homing logic: update target position if unit moves
            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = p.speed * dt;

            p.trail.push({x: p.x, y: p.y});
            if (p.trail.length > 20) p.trail.shift();

            // Hit Detection
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId) || engine.agents[0]; 

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const radius = p.skill.aoeRadius || 1;
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);
                    targets.forEach(t => { if (source) this.applyDamage(source, t, p.skill, hitPos, engine); });
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) this.applyDamage(source, target, p.skill, undefined, engine);
                    }
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: p.x, y: p.y}, skill: p.skill });
                }

                const lastIdx = this.projectiles.length - 1;
                if (i !== lastIdx) {
                    this.projectiles[i] = this.projectiles[lastIdx];
                }
                this.projectiles.pop();

            } else {
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    // =========================================================================================
    // 💥 SKILL EXECUTION (Instant)
    // =========================================================================================

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: Hex | null = null;

        // 1. Identify Targets
        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            // Single Target - Verify Height-Aware Range
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                const actualDist = HexUtils.dist(source, source.target);

                if (actualDist <= effectiveRange) {
                    targets = [source.target];
                }
            }
        }

        const origin = {x: source.px, y: source.py};

        // 2. VISUAL ENFORCEMENT: Beam/Tracer for Ranged Instant Attacks
        // If range > 1, we MUST draw a line. If range == 1, it's melee (SMASH/SLASH) handles itself via hit effect.
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({
                    type: 'VISUAL_BEAM',
                    pos: { x: t.px, y: t.py }, // Beam End Point
                    sourceId: source.id,
                    targetId: t.id,
                    skill: skill,
                    color: skill.color
                });
            }
            this.applyDamage(source, t, skill, origin, engine);
        });

        // 3. Melee / Self / Miss Visuals
        if (targets.length === 0 && skill.type === 'AOE' && centerHex) {
             // Missed/Ground Hit logic if needed, but CAST_FINISH handles the ground circle/smash visual
        }

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public applyDamage(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            const originX = origin ? origin.x : source.px;
            const originY = origin ? origin.y : source.py;
            let dx = target.px - originX;
            let dy = target.py - originY;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len > 0) {
                dx /= len; dy /= len;
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += dx * impactForce;
                target.physics.vy += dy * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        // EMIT EVENT
        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        engine.log(source, '命中', target.id, `${skill.name} ${rawDmg > 0 ? `-${rawDmg}` : (rawDmg < 0 ? `+${-rawDmg}` : '')}`);
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    if (!engine.isValid(bestN.q, bestN.r)) break; 
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; 

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) break; 
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) break; 

                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

import { GameEngine } from "../game";
import { HexUtils, Vector, MapConfig } from "../utils";
import { AssetManager } from "../assets";
import { RenderableItem } from "./grid";
import { SceneTheme, Team } from "../../types";
import { PALETTE } from "../../constants";

const UNIT_CHEST_HEIGHT = 40;
const GRAVITY = 1800; // Gravity for particles

interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
}

interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

interface GridFlash {
    q: number;
    r: number;
    color: string;
    life: number;
}

export class VFXSystem {
    public particles: Particle[] = [];
    public decals: Decal[] = [];
    public gridFlashes: GridFlash[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    private getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK' 
        };
    }

    private releaseParticle(p: Particle) {
        p.active = false;
        this.particlePool.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string) {
        // Update Particles
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.releaseParticle(p);
                this.particles.splice(i, 1);
                continue;
            }

            // Physics Integration
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.z += p.vz * dt;
            p.rotation += p.vRotation * dt;

            // Gravity & Environment Logic
            if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                p.vz -= GRAVITY * dt; // Gravity

                // Ground Bounce
                if (p.z < 0) {
                    p.z = 0;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; // Friction
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        p.vz = 0;
                        p.vx *= 0.1; // Stop sliding
                        p.vy *= 0.1;
                    }
                }
            } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                p.vx *= 0.90; 
                p.vy *= 0.90;
                p.vz *= 0.90; // Drag
            }
        }

        // Update Decals
        for (let i = this.decals.length - 1; i >= 0; i--) {
            this.decals[i].life -= dt * 0.5;
            if (this.decals[i].life <= 0) this.decals.splice(i, 1);
        }

        // Update Grid Flashes
        for (let i = this.gridFlashes.length - 1; i >= 0; i--) {
            this.gridFlashes[i].life -= dt * 2.0;
            if (this.gridFlashes[i].life <= 0) this.gridFlashes.splice(i, 1);
        }
    }

    // --- Spawners ---

    spawnUnitShatter(x: number, y: number, team: Team) {
        // Colors
        // Blue: Silver armor, Gold trim, Blue energy
        // Red: Iron armor, Bone trim, Red energy
        const armorColor = team === Team.BLUE ? '#e2e8f0' : '#27272a';
        const trimColor = team === Team.BLUE ? '#fbbf24' : '#a1a1aa';
        const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

        // 1. Armor Shards (Heavy chunks)
        for (let i = 0; i < 6; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = 150 + Math.random() * 200;
            const p = this.getParticle();

            p.x = x; p.y = y; p.z = 30 + Math.random() * 30; // Start at chest height
            p.vx = Math.cos(angle) * speed;
            p.vy = Math.sin(angle) * speed;
            p.vz = 200 + Math.random() * 300; // Pop up

            p.life = 2.0; p.maxLife = 2.0;
            p.color = Math.random() > 0.5 ? armorColor : trimColor;
            p.size = 6 + Math.random() * 6;
            p.type = 'SHARD';
            p.rotation = Math.random() * Math.PI;
            p.vRotation = (Math.random() - 0.5) * 20;
            p.delay = 0;
            this.particles.push(p);
        }

        // 2. Core Sparks (Energy leak)
        this.spawnExplosion(x, y, 30, 15, coreColor, 1.5, 0.8, 'SPARK');

        // 3. Shockwave
        this.addImpact(x, y, coreColor, 'RING', 0.5);

        // 4. Ground Scorch
        this.addDecal(x, y, '#000');
    }

    spawnBeam(sx: number, sy: number, tx: number, ty: number, color: string) {
        const p = this.getParticle();
        p.x = sx; p.y = sy; p.z = 0;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.targetX = tx; p.targetY = ty;
        p.life = 0.5; p.maxLife = 0.5;
        p.color = color; p.size = 5;
        p.type = 'BEAM';
        p.delay = 0;
        this.particles.push(p);
    }

    spawnDomainExpansion(x: number, y: number, color: string, duration: number) {
        const p = this.getParticle();
        p.x = x; p.y = y; p.z = 10;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = duration; p.maxLife = duration;
        p.color = color; p.size = 0;
        p.type = 'DOMAIN';
        p.delay = 0;
        this.particles.push(p);
    }

    spawnExplosion(x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
        const actualCount = type === 'SPARK' ? count * 1.5 : count;

        for (let i = 0; i < actualCount; i++) {
            const angle = Math.random() * Math.PI * 2;
            const spd = Math.random() * 150 * speed;
            const p = this.getParticle();

            p.x = x; p.y = y; p.z = z;
            p.vx = Math.cos(angle) * spd;
            p.vy = Math.sin(angle) * spd;
            p.vz = (Math.random() * 150 + 50) * speed; // Sparks fly up
            p.life = life * (0.5 + Math.random() * 0.5);
            p.maxLife = life;
            p.color = color;
            p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 3 + 1;
            p.type = type;
            p.delay = 0;

            this.particles.push(p);
        }
    }

    spawnDebris(x: number, y: number, color: string, count: number) {
        // Fallback for generic debris
        for (let i = 0; i < count; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 50 + 20;
            const p = this.getParticle();

            p.x = x; p.y = y; p.z = 20;
            p.vx = Math.cos(angle) * speed;
            p.vy = Math.sin(angle) * speed;
            p.vz = Math.random() * 100 + 100;
            p.life = 2.0; p.maxLife = 2.0;
            p.color = color; p.size = Math.random() * 4 + 2;
            p.type = 'DEBRIS';
            p.delay = 0;

            this.particles.push(p);
        }
    }

    spawnTeleport(x: number, y: number, color: string) {
        this.spawnPillar(x, y, color, 1.0, 0);
        this.addImpact(x, y, color, 'RING', 1.0);
    }

    spawnDivinePillar(x: number, y: number, color: string, life: number, delay: number = 0) {
        this.spawnPillar(x, y, color, life, delay);
    }

    spawnPillar(x: number, y: number, color: string, life: number, delay: number = 0) {
        const p = this.getParticle();
        p.x = x; p.y = y; p.z = 0;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = life; p.maxLife = life;
        p.color = color; p.size = 100;
        p.type = 'PILLAR';
        p.delay = delay;
        this.particles.push(p);
    }

    spawnShockwave(x: number, y: number, color: string, life: number) {
        const p = this.getParticle();
        p.x = x; p.y = y; p.z = 10;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = life; p.maxLife = life;
        p.color = color; p.size = 0;
        p.type = 'SHOCKWAVE';
        p.delay = 0;
        this.particles.push(p);
    }

    addGridFlash(q: number, r: number, color: string) {
        this.gridFlashes.push({ q, r, color, life: 1.0 });
    }

    addImpact(x: number, y: number, color: string, type: 'RING', life: number) {
        const p = this.getParticle();
        p.x = x; p.y = y; p.z = 5;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = life; p.maxLife = life;
        p.color = color; p.size = 0;
        p.type = type;
        p.delay = 0;
        this.particles.push(p);
    }

    addDecal(x: number, y: number, color: string) {
        this.decals.push({
            x, y, color, life: 10.0, scale: 0.5 + Math.random() * 0.5
        });
    }

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    collectRenderables(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        this.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 // Apply Arc to ARROW, FIREBALL, and BOMB
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Calculate Pitch Rotation (Visual Angle)
             // Use current direction to target to allow for homing curves
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);

             // SAFE FALLBACK: If extremely close, keep moving towards target (or use last known good dir)
             // to prevent NaN when normalization fails on 0-length vector
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 // Fallback to overall trajectory logic to prevent snap
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);

             // Extra rotation for bombs (spin)
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // Draw Shadow
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 10, 5, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // Draw Projectile
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') {
                        ctx.rotate(spin);
                    } else {
                        ctx.rotate(angle);
                    }

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);

                    // DEBUG: Visual Fallback for Missing Assets
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    } else {
                        // Draw pink box if asset is broken
                        ctx.fillStyle = '#ff00ff';
                        ctx.fillRect(-5, -5, 10, 10);
                    }

                    ctx.restore();
                 }
             });
        });

        return list;
    }

    drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        this.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            // Z acts as Y-offset in 2D draw call (up is negative)
            const drawY = p.y + offset - p.z;

            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); // Ground effects
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress);
                ctx.restore();
                return;
            }

            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 5;
                    ctx.lineCap = 'round';
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.beginPath();
                    ctx.moveTo(0, 0);
                    ctx.lineTo(p.targetX - p.x, p.targetY - p.y); 
                    ctx.stroke();
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                // Drawing Shards as jagged polygons
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);

                // Draw a rough triangle/quad shape
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    // Jagged Shard
                    ctx.moveTo(-s, -s/2);
                    ctx.lineTo(0, -s);
                    ctx.lineTo(s, -s/2);
                    ctx.lineTo(0, s);
                } else {
                    // Box debris
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();

                // Add highlight edge
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const pulse = 1 + Math.sin(progress * 15) * 0.1;
        const baseWidth = 50 * (lifeRatio < 0.2 ? lifeRatio * 5 : 1) * pulse;
        const height = 1000;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 1.5;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.5, 0, 0, ringSize);
        ringGrad.addColorStop(0, 'rgba(255,255,255,0)');
        ringGrad.addColorStop(0.5, p.color);
        ringGrad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#fff');
        coreGrad.addColorStop(0.3, 'rgba(255,255,255,0.2)');
        coreGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
        glowGrad.addColorStop(0, p.color);
        glowGrad.addColorStop(0.5, 'transparent');

        ctx.fillStyle = glowGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.fillRect(-baseWidth * 0.8, -height, baseWidth * 1.6, height);
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.scale(1, 0.55); 
        const r = progress * 250; 
        const width = 30 * (1 - progress);
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         ctx.scale(1, 0.55); 
         ctx.fillStyle = p.color;
         ctx.globalAlpha = 0.3 * (1 - progress);
         ctx.globalCompositeOperation = 'screen';
         ctx.beginPath(); ctx.arc(0, 0, 250, 0, Math.PI * 2); ctx.fill();
         ctx.strokeStyle = p.color;
         ctx.lineWidth = 2;
         ctx.beginPath(); ctx.arc(0, 0, 250, 0, Math.PI*2); ctx.stroke();
    }
}

